import{_ as s,C as r,c as n,o as i,a3 as t,G as a}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"One step flow","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/routes/one-step-flow.md","filePath":"master/supply-chain/inventories/routes/one-step-flow.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/inventories/routes/one-step-flow.md"};function d(h,e,c,p,u,m){const o=r("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="one-step-flow" tabindex="-1">One step flow <a class="header-anchor" href="#one-step-flow" aria-label="Permalink to &quot;One step flow&quot;">​</a></h1><p>In the one step flow, goods go directly between the outside world and your main stock. Receipts land in <code>WH/Stock</code>. Deliveries leave from <code>WH/Stock</code>. It suits small teams where one person receives, stores and ships.</p><blockquote><p><strong>In simple words:</strong> One document to receive, one document to deliver. No extra stops.</p></blockquote><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><ul><li>You have a small stock room.</li><li>Nobody inspects goods before storing them.</li><li>You do not pack orders in a separate area.</li></ul><h2 id="set-it-in-the-warehouse" tabindex="-1">Set it in the warehouse <a class="header-anchor" href="#set-it-in-the-warehouse" aria-label="Permalink to &quot;Set it in the warehouse&quot;">​</a></h2><ol><li>Open <code>Inventory → Configurations → Warehouse Management → Warehouses</code>.</li><li>Open your warehouse and click <strong>Edit</strong>.</li><li>In <strong>Shipment Management</strong>, set <strong>Incoming Shipments</strong> to <strong>Receive and Store (One step)</strong>.</li><li>Set <strong>Outgoing Shipments</strong> to <strong>Deliver (One step)</strong>.</li><li>Click <strong>Save changes</strong>.</li></ol>',7)),a(o,{src:"/images1/inventory/route_wh_one_step.png",alt:"Warehouse edit form with the radio changed on screen but not yet saved: Incoming Shipments Receive and Store (One step) and Outgoing Shipments Deliver (One step) selected"}),e[1]||(e[1]=t('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These options show only when <code>Inventory → Settings → Manage Warehouses → Multi Steps Routes</code> is on. Without it, the warehouse works in one step.</p></div><h2 id="documents-created" tabindex="-1">Documents created <a class="header-anchor" href="#documents-created" aria-label="Permalink to &quot;Documents created&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Order</th><th>Document</th><th>Prefix</th><th>From → To</th></tr></thead><tbody><tr><td>Purchase order</td><td>Receipt</td><td>WH/IN</td><td>Partners/Vendors → WH/Stock</td></tr><tr><td>Sales order</td><td>Delivery</td><td>WH/OUT</td><td>WH/Stock → Partners/Customers</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>You buy 20 Camping Hammocks on a purchase order.</p><ol><li>Confirm the purchase order. A receipt WH/IN/n appears.</li><li>Open the receipt from <code>Inventory → Operations → Transfers → Receipts</code>.</li><li>Click <strong>Validate</strong> when the boxes arrive.</li><li>The hammocks are now in <code>WH/Stock</code>. Stock rises by 20.</li></ol><p>The screenshot comes from the three-step dev warehouse, so it shows <code>WH/Input</code> as the destination. In a one-step warehouse the destination is <code>WH/Stock</code>.</p>',7)),a(o,{src:"/images1/inventory/route_one_step_receipt.png",alt:"Receipt WH/IN/11 in Ready state with destination WH/Input and the Validate button, taken from the three-step dev warehouse"}),e[2]||(e[2]=t('<p>For a sale, confirming the sales order creates WH/OUT. Click <strong>Validate</strong> when the parcel leaves. Stock falls and the goods sit in <code>Partners/Customers</code>.</p><h2 id="what-you-do-at-each-step" tabindex="-1">What you do at each step <a class="header-anchor" href="#what-you-do-at-each-step" aria-label="Permalink to &quot;What you do at each step&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Your action</th></tr></thead><tbody><tr><td>Receive</td><td>Validate the receipt</td></tr><tr><td>Deliver</td><td>Validate the delivery</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Routes overview</a></li><li><a href="./two-step-flow.html">Two step flow</a></li><li><a href="./../operations/receipts.html">Receipts</a></li><li><a href="./../operations/deliveries.html">Deliveries</a></li><li><a href="./../../purchase/orders/purchase-orders.html">Purchase orders</a></li></ul>',5))])}const f=s(l,[["render",d]]);export{g as __pageData,f as default};
